mapper.select:
SELECT st.seat_seq AS seatSeq, st.schedule_seq AS scheduleSeq, st.car_no AS carNo, st.seat_no AS seatNo, st.seat_grade AS seatGrade, COALESCE(r.status, 'HELD') AS status, st.version FROM seat st LEFT JOIN reservation r ON st.seat_seq = r.seat_seq AND r.status IN ('HELD', 'CONFIRMED') WHERE st.schedule_seq = #{scheduleSeq}
AND st.car_no = #{carNo}
ORDER BY st.car_no ASC, CAST(NULLIF(regexp_replace(st.seat_no, '\D', '', 'g'), '') AS INTEGER) ASC, regexp_replace(st.seat_no, '\d', '', 'g') ASC
